INSERT INTO posts (id, image_id, title, slug, description, content, views, published_at) VALUES
    (1, 1, 'Как выбрать фотохостинг', 'how-to-choose-photo-hosting', 'Разбираем основные возможности современного сервиса для хранения изображений', 'При выборе фотохостинга важно учитывать ограничения на размер файлов, поддержку нужных форматов, скорость загрузки и правила хранения оригиналов. Отдельного внимания заслуживают приватность альбомов и возможность получить прямую ссылку на изображение.', 184, '2026-01-12 10:00:00'),
    (2, 2, 'JPEG, WebP или AVIF: какой формат использовать', 'jpeg-webp-or-avif', 'Сравниваем популярные форматы для публикации фотографий в интернете', 'JPEG остаётся универсальным форматом для фотографий, WebP обеспечивает хорошее соотношение качества и размера, а AVIF способен сжимать изображения ещё эффективнее. Итоговый выбор зависит от поддержки браузерами и требований к качеству.', 267, '2026-01-18 12:30:00'),
    (3, 3, 'Зачем фотохостингу отдельные превью', 'why-photo-hosting-needs-previews', 'Как уменьшенные копии ускоряют страницы с большим количеством фотографий', 'Загрузка оригиналов в списках изображений расходует трафик и замедляет отображение страницы. Превью фиксированного размера позволяют быстро построить галерею, а полноразмерный файл загружается только при открытии фотографии.', 231, '2026-01-25 09:15:00'),
    (4, 4, 'Как CDN ускоряет загрузку изображений', 'how-cdn-delivers-images', 'Объясняем доставку фотографий через географически распределённые серверы', 'CDN сохраняет копии изображений ближе к пользователям и сокращает задержку при загрузке. Для фотохостинга это особенно важно, поскольку изображения обычно занимают значительно больше места, чем HTML и стили страницы.', 156, '2026-02-02 14:00:00'),
    (5, 5, 'Какие метаданные хранит фотография', 'photo-metadata-explained', 'Разбираемся с EXIF, датой съёмки, геолокацией и данными камеры', 'Фотография может содержать модель камеры, параметры съёмки, дату и координаты. Перед публичной публикацией полезно решить, какие метаданные сохранить, а какие удалить для защиты приватности пользователя.', 119, '2026-02-10 11:45:00'),
    (6, 6, 'Как сжимать фотографии без заметной потери качества', 'compress-images-without-visible-quality-loss', 'Подбираем размер и качество изображения для быстрой загрузки', 'Слишком сильное сжатие создаёт артефакты, а слишком слабое оставляет файл неоправданно большим. Оптимальные параметры зависят от разрешения, формата и количества мелких деталей в исходной фотографии.', 298, '2026-02-17 16:20:00'),
    (7, 7, 'Как не потерять загруженные фотографии', 'reliable-photo-storage', 'Резервные копии и контроль целостности файлов на фотохостинге', 'Надёжное хранение требует резервных копий, проверки целостности и контроля ошибок записи. База данных хранит сведения об изображении, но сами файлы должны дополнительно защищаться от случайного удаления и отказа оборудования.', 143, '2026-02-23 13:10:00'),
    (8, 8, 'Безопасная загрузка изображений', 'secure-image-upload', 'Проверяем формат, размер и содержимое пользовательского файла', 'Расширению файла нельзя доверять без проверки. Фотохостинг должен ограничивать размер загрузки, определять реальный MIME-тип, генерировать собственное имя файла и не допускать выполнение загруженного содержимого.', 322, '2026-03-01 10:40:00');
